import {C,$,esc,toast,save,on,wait} from './studio-ui.js';
import {boardStale,generationReady} from './workflow-store.js';
let timer;
function timeline(){const s=C.s,order=s.finishing.order||s.shots.map(x=>x.id);return [...order,...s.shots.map(x=>x.id).filter(id=>!order.includes(id))].map(id=>s.shots.find(x=>x.id===id)).filter(Boolean).map(sh=>({...sh,duration:s.finishing.durations?.[sh.id]??sh.duration}));}
export function finishPage(){const s=C.s,list=timeline(),missing=s.shots.filter(sh=>!sh.video||sh.videoStale),ready=generationReady(s)&&!missing.length;return `<div class="page-heading"><div><p class="eyebrow">共用步骤 / 成片</p><h1>检查节奏，准备导出</h1><p>${list.length} 个镜头 · 合计 ${list.reduce((n,x)=>n+x.duration,0)} 秒 · ${s.aspect}</p></div><span class="demo-label">交互原型 · 无真实合成</span></div><section class="notice ${ready?'success':'warning'}" id="export-check">${ready?'素材检查通过。预览后可演示导出。':`请返回分镜处理：${boardStale(s)?'剧本来源已变；':''}${missing.length?'视频缺失或待更新；':''}${!generationReady(s)?'分镜、参考图或图片引用未完成确认。':''}`}<a href="./storyboard.html" data-nav="storyboard">返回分镜</a></section><div class="finish-layout"><section class="panel" id="timeline-editor"><h2>导出设置</h2><div class="export-options"><label class="field">文件名<input id="export-name" value="${esc(s.finishing.fileName||s.projectName||s.title)}"></label><div class="field-pair"><label class="field">分辨率<select id="export-resolution">${['720P','1080P','4K'].map(x=>`<option ${x===(s.finishing.resolution||'1080P')?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">帧率<select id="export-fps">${[24,25,30,60].map(x=>`<option ${x===(s.finishing.fps||30)?'selected':''}>${x}</option>`).join('')}</select></label></div><p class="helper">MP4 合成演示 · ${s.aspect} · 剪映工程后续支持</p></div><details class="clip-edit-list" open><summary>镜头顺序与时长</summary>${list.map((sh,i)=>`<div class="finish-row"><div><strong>${i+1} · 镜头</strong><p>${esc(sh.dialogue||'无台词')}</p><small>${sh.audio?sh.audio.stale?'音频待更新':'独立 TTS 示例已生成':'未生成 TTS 音频'}</small></div><label class="field">秒<input type="number" min="1" max="90" data-time="${sh.id}" value="${sh.duration}"></label><select data-order="${sh.id}" aria-label="镜头 ${i+1} 顺序">${list.map((_,n)=>`<option value="${n}" ${n===i?'selected':''}>第 ${n+1} 镜</option>`).join('')}</select></div>`).join('')||'<p>先完成剧本和分镜制作。</p>'}</details><details open><summary>声音与字幕设置</summary><div class="field-pair"><label class="field">配乐方向<input id="finish-music" type="text" value="${esc(s.finishing.music)}"></label><label class="field">音色方向<input id="finish-voice" type="text" value="${esc(s.finishing.voice)}"></label></div><label class="check"><input type="checkbox" id="finish-subtitles" ${s.finishing.subtitles?'checked':''}>显示字幕</label><p class="helper">TTS 在分镜页单独生成。原型不合成真实音频，台词朗读使用浏览器能力。</p></details><p class="helper">成片排序独立保存，不改写已质检的分镜；更改顺序后请检查尾帧衔接及音画同步。</p><div class="section-end"><button class="text-button" id="download-plan">下载制作清单</button><button class="button primary" id="export-demo" ${ready?'':'disabled'}>导出成片（演示）</button></div><p id="export-status" role="status"></p></section><aside class="panel" id="finish-preview"><div class="panel-header"><h2>作品预览</h2><span class="pill">${s.aspect}</span></div><div class="preview-frame" id="preview-frame" style="aspect-ratio:${s.aspect.replace(':','/')}"><p>分镜示意预览<br>非真实合成视频</p></div><div class="clip-strip">${list.map((sh,i)=>`<button class="clip-tile" data-preview-shot="${sh.id}"><span>镜头 ${i+1}</span><small>${sh.duration}s</small><p>${esc(sh.dialogue.slice(0,20)||'画面')}</p></button>`).join('')}</div><button class="button" id="play-preview" ${list.length?'':'disabled'}>预览镜头顺序</button></aside></div><section class="panel timeline-panel"><h2>作品时间轴</h2><p class="helper">按镜头展示节奏；在右侧调整顺序和时长。此处为轨道示意，不支持拖拽剪辑。</p>${[['视频','video'],['配音','audio'],['字幕','subtitle']].map(([label,key])=>`<div class="track"><span>${label}</span><div class="track-clips">${list.map((sh,i)=>`<div style="flex:${sh.duration}" class="track-${key}">${key==='video'?`镜头${i+1} · ${sh.duration}s`:key==='audio'?(sh.audio?'TTS示例':'未生成'):(s.finishing.subtitles?esc(sh.dialogue.slice(0,18)):'关闭')}</div>`).join('')}</div></div>`).join('')}</section>`;}
export function bindFinish(){const s=C.s;for(const [id,key]of [['export-name','fileName'],['export-resolution','resolution'],['export-fps','fps']])$(id).onchange=e=>{s.finishing[key]=key==='fps'?+e.target.value:e.target.value;save()};document.querySelectorAll('[data-preview-shot]').forEach(b=>b.onclick=()=>{const sh=s.shots.find(x=>x.id===b.dataset.previewShot);$('preview-frame').innerHTML=sh.video?.data?`<video controls src="${esc(sh.video.data)}"></video>`:`<strong>镜头示意</strong><p>${esc(sh.dialogue)}</p><small>非真实合成视频</small>`});document.querySelectorAll('[data-time]').forEach(e=>e.onchange=()=>{if(!Number.isFinite(+e.value)||+e.value<1||+e.value>90){toast('请输入 1–90 秒');C.render();return}s.finishing.durations??={};s.finishing.durations[e.dataset.time]=+e.value;save();C.render();toast('时长已更新，请检查音画同步')});document.querySelectorAll('[data-order]').forEach(e=>e.onchange=()=>{const list=timeline().map(x=>x.id),i=list.indexOf(e.dataset.order);list.splice(i,1);list.splice(+e.value,0,e.dataset.order);s.finishing.order=list;save();C.render();toast('已调整成片顺序，请检查前后镜头衔接')});for(const[id,key]of [['finish-voice','voice'],['finish-music','music']])$(id).oninput=e=>{s.finishing[key]=e.target.value;save()};$('finish-subtitles').onchange=e=>{s.finishing.subtitles=e.target.checked;save()};on('play-preview',()=>{clearInterval(timer);let i=0;const list=timeline();const show=()=>{const sh=list[i++];$('preview-frame').innerHTML=`<strong>镜头 ${i}</strong><p>${esc(sh.prompt.replace(/@\[[^\]]+\]/g,'').slice(0,180))}</p>${s.finishing.subtitles?`<p>「${esc(sh.dialogue)}」</p>`:''}`;};show();timer=setInterval(()=>{if(i>=list.length){clearInterval(timer);return}show()},1800)});on('export-demo',async()=>{$('export-demo').disabled=true;$('export-status').textContent='演示：排队 → 合成中…';await wait(600);$('export-status').textContent='导出流程演示完成；未接入编码服务，不产生 MP4。可下载制作清单用于评审。';$('export-demo').disabled=false});on('download-plan',()=>{const data={demo:true,workflow:s.mode,duration:timeline().reduce((n,x)=>n+x.duration,0),aspect:s.aspect,exportSettings:s.finishing,novel:s.selectedNovel,script:s.final,shots:timeline().map(sh=>({id:sh.id,dialogue:sh.dialogue,prompt:sh.prompt,duration:sh.duration,assets:sh.assets.map(({id,kind,name,version})=>({id,kind,name,version})),previousVideoId:sh.video?.snapshot?.previousVideoId||null,audio:sh.audio?{text:sh.audio.text,stale:sh.audio.stale}:null}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='mengyuan-novel-production-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});}
